mapper.select:
select t.cf_id cfId, t.contract_id contractId, t.fee_seq feeSeq, t.config_id configId,
t.fee_type_cd feeTypeCd, t.fee_type_name feeTypeName, t.fee_name feeName,
t.computing_formula computingFormula, t.computing_formula_name computingFormulaName,
t.unit_price unitPrice, t.additional_amount additionalAmount, t.cycle cycle, t.months months,
t.coefficient coefficient, t.manual_amount manualAmount, t.base_amount baseAmount, t.amount amount,
t.include_in_amount includeInAmount, t.compute_remark computeRemark, t.remark remark,
t.store_id storeId, t.status_cd statusCd, t.create_time createTime
from contract_fee t
where 1 = 1

    and t.cf_id = #{cfId}


    and t.contract_id = #{contractId}


    and t.contract_id in

        #{item}



    and t.status_cd = #{statusCd}


    and t.store_id = #{storeId}

order by t.fee_seq asc, t.create_time asc

    limit #{page}, #{row}

select count(1) count
from contract_fee t
where 1 = 1

    and t.cf_id = #{cfId}


    and t.contract_id = #{contractId}


    and t.contract_id in

        #{item}



    and t.status_cd = #{statusCd}


    and t.store_id = #{storeId}
